const p = $('Read Pricing tab').item.json;
const offers = $json.payload?.Offers || [];
const others = offers.filter(o => !o.MyOffer).map(o => Number(o.ListingPrice?.Amount||0)).filter(Boolean);
const lowest = others.length ? Math.min(...others) : null;
const my = Number(p.MyPrice||0), floor = Number(p.FloorPrice||0);
if (!lowest || lowest >= my) return [];
const suggest = Math.max(floor, Math.floor(lowest * 0.99));
if (suggest >= my) return [];
return [{ json: { SKU: p.SKU, my, lowest, suggest, floor, row_number: p.row_number } }];

