const html = typeof $json.data === 'string' ? $json.data : ($json.body || '');
const m = String(html).match(/₹\s?([0-9][0-9,]{2,})/);
const price = m ? Number(m[1].replace(/,/g,'')) : null;
const prev = Number($('Read competitor URLs').item.json.LastPrice||0);
if (!price) return [];
const moved = prev && Math.abs(price-prev)/prev > 0.03;
return [{ json: { Name: $('Read competitor URLs').item.json.Name, price, prev, moved, row_number: $('Read competitor URLs').item.json.row_number } }];
